import{_ as p,a0 as r,w as o,s as d,ao as l,I as t,a1 as i,A as n,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"NoSQL： 如何在 Ubuntu 16.04 上安装 OrientDB | LCTT x X-CMD","titleTemplate":false,"description":"NoSQL： 如何在 Ubuntu 16.04 上安装 OrientDB | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"NoSQL： 如何在 Ubuntu 16.04 上安装 OrientDB | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"NoSQL： 如何在 Ubuntu 16.04 上安装 OrientDB | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170712 NoSQL How To Install OrientDB on Ubuntu 16.04","title":"NoSQL： 如何在 Ubuntu 16.04 上安装 OrientDB","tag":"201707","desc":""},"relativePath":"201707/20170712 NoSQL How To Install OrientDB on Ubuntu 16.04.md","filePath":"[post].md"}'),h={name:"201707/20170712 NoSQL How To Install OrientDB on Ubuntu 16.04.md"};function b(c,s,g,u,k,f){const a=r("Link");return o(),d("div",null,[s[17]||(s[17]=l('<h1 id="nosql-如何在-ubuntu-16-04-上安装-orientdb" tabindex="-1">NoSQL： 如何在 Ubuntu 16.04 上安装 OrientDB <a class="header-anchor" href="#nosql-如何在-ubuntu-16-04-上安装-orientdb" aria-label="Permalink to “NoSQL： 如何在 Ubuntu 16.04 上安装 OrientDB”">​</a></h1><p><img src="https://www.unixmen.com/wp-content/uploads/2017/07/orientdb-696x318.png" alt="OrientDB NoSQL DBMS" title="orientdb"></p><h3 id="说明-非关系型数据库-nosql-和-orientdb" tabindex="-1">说明 - 非关系型数据库（NoSQL）和 OrientDB <a class="header-anchor" href="#说明-非关系型数据库-nosql-和-orientdb" aria-label="Permalink to “说明 - 非关系型数据库（NoSQL）和 OrientDB”">​</a></h3><p>通常在我们提及数据库的时候，想到的是两个主要的分类：使用用于用户和应用程序之间进行对接的一种被称为结构化查询语言（<strong>S</strong>tructured <strong>Q</strong>uery <strong>L</strong>anguage ，缩写 SQL）的关系型数据库管理系统（<strong>R</strong>elational <strong>D</strong>ata <strong>b</strong>ase <strong>M</strong>anagement <strong>S</strong>ystem，缩写 RDBMS） 以及非关系型数据库管理系统（non-relational database management systems 或称 NoSQL 数据库）。</p><p>这两种模型在如何处理（存储）数据的方面存在着巨大的差异。</p><h4 id="关系数据库管理系统" tabindex="-1">关系数据库管理系统 <a class="header-anchor" href="#关系数据库管理系统" aria-label="Permalink to “关系数据库管理系统”">​</a></h4><p>在关系模型中（如 MySQL，或者其分支 MariaDB），一个数据库是一个表的集合，其中每个表包含一个或多个以列组织的数据分类。数据库的每行包含一个唯一的数据实例，其分类由列定义。</p><p>举个例子，想象一个包含客户的表。每一行相当于一个客户，而其中的每一列分别对应名字、地址以及其他所必须的信息。</p><p>而另一个表可能是包含订单、产品、客户、日期以及其它的种种。而这个数据库的使用者则可以获得一个满足其需要的视图，例如一个客户在一个特定的价格范围购买产品的报告。</p><h4 id="非关系型数据库管理系统" tabindex="-1">非关系型数据库管理系统 <a class="header-anchor" href="#非关系型数据库管理系统" aria-label="Permalink to “非关系型数据库管理系统”">​</a></h4><p>在非关系型数据库（或称为<ruby>不仅仅是数据库<rt>Not only SQL</rt></ruby>）管理系统中，数据库被设计为使用不同的方式存储数据，比如文档存储、键值对存储、图形关系存储以及其他方式存储。使用此种形式实现的数据库系统专门被用于大型数据库集群和大型 Web 应用。现今，非关系型数据库被用于某些大公司，如谷歌和亚马逊。</p><h5 id="文档存储数据库" tabindex="-1">文档存储数据库 <a class="header-anchor" href="#文档存储数据库" aria-label="Permalink to “文档存储数据库”">​</a></h5><p>文档存储数据库是将数据用文档的形式存储。这种类型的运用通常表现为 JavaScript 和 JSON，实际上，XML 和其他形式的存储也是可以被采用的。这里的一个例子就是 MongoDB。</p><h5 id="键值对存储数据库" tabindex="-1">键值对存储数据库 <a class="header-anchor" href="#键值对存储数据库" aria-label="Permalink to “键值对存储数据库”">​</a></h5><p>这是一个由唯一的<ruby>键<rt>key</rt></ruby>配对一个<ruby>值<rt>value</rt></ruby>的简单模型。这个系统在高速缓存方面具有高性能和高度可扩展性。这里的例子包括 BerkeleyDB 和 MemacacheDB。</p><h5 id="图形关系数据库" tabindex="-1">图形关系数据库 <a class="header-anchor" href="#图形关系数据库" aria-label="Permalink to “图形关系数据库”">​</a></h5><p>正如其名，这种数据库通过使用<ruby>图<rt>graph</rt></ruby>模型存储数据，这意味着数据通过节点和节点之间的互连进行组织。这是一个可以随着时间的推移和使用而发展的灵活模型。这个系统应用于那些强调映射关系的地方。这里的例子有 IBM Graphs、Neo4j 以及 <strong>OrientDB</strong>。</p><h3 id="orientdb" tabindex="-1">OrientDB <a class="header-anchor" href="#orientdb" aria-label="Permalink to “OrientDB”">​</a></h3>',18)),t("p",null,[i(a,{href:"https://orientdb.com/"},{default:n(()=>[...s[0]||(s[0]=[e("OrientDB",-1)])]),_:1}),s[1]||(s[1]=e(" 是一个多模式的非关系型数据库管理系统。正如开发它的公司所说的“",-1)),s[2]||(s[2]=t("em",null,[e("它是一个将图形关系与文档、键值对、反应性、面向对象和地理空间模型结合在一起的"),t("strong",null,"可扩展的、高性能的数据库")],-1)),s[3]||(s[3]=e("”。",-1))]),s[18]||(s[18]=l(`<p>OrientDB 还支持 SQL ，经过扩展可以用来操作树和图。</p><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to “目标”">​</a></h3><p>这个教程旨在教会大家如何在运行 Ubuntu 16.04 的服务器上下载并配置 OrientDB 社区版。</p><h3 id="下载-orientdb" tabindex="-1">下载 OrientDB <a class="header-anchor" href="#下载-orientdb" aria-label="Permalink to “下载 OrientDB”">​</a></h3><p>我们可以从最新的服务端上通过输入下面的指令来下载最新版本的 OrientDB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget -O orientdb-community-2.2.22.tar.gz http://orientdb.com/download.php?file=orientdb-community-2.2.22.tar.gz&amp;os=linux</span></span></code></pre></div><p>这里下载的是一个包含预编译二进制文件的压缩包，所以我们可以使用 <code>tar</code> 指令来操作解压它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -zxf orientdb-community-2.2.22.tar.gz</span></span></code></pre></div><p>将从中提取出来的文件夹整体移动到 <code>/opt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mv orientdb-community-2.2.22 /opt/orientdb</span></span></code></pre></div><h3 id="启动-orientdb-服务器" tabindex="-1">启动 OrientDB 服务器 <a class="header-anchor" href="#启动-orientdb-服务器" aria-label="Permalink to “启动 OrientDB 服务器”">​</a></h3><p>启动 OrientDB 服务器需要运行 <code>orientdb/bin/</code> 目录下的 shell 脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /opt/orientdb/bin/server.sh</span></span></code></pre></div><p>如果你是第一次开启 OrientDB 服务器，安装程序还会显示一些提示信息，以及提醒你设置 OrientDB 的 root 用户密码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+---------------------------------------------------------------+</span></span>
<span class="line"><span>| WARNING: FIRST RUN CONFIGURATION |</span></span>
<span class="line"><span>+---------------------------------------------------------------+</span></span>
<span class="line"><span>| This is the first time the server is running. Please type a |</span></span>
<span class="line"><span>| password of your choice for the &#39;root&#39; user or leave it blank |</span></span>
<span class="line"><span>| to auto-generate it. |</span></span>
<span class="line"><span>| |</span></span>
<span class="line"><span>| To avoid this message set the environment variable or JVM |</span></span>
<span class="line"><span>| setting ORIENTDB_ROOT_PASSWORD to the root password to use. |</span></span>
<span class="line"><span>+---------------------------------------------------------------+</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Root password [BLANK=auto generate it]: ********</span></span>
<span class="line"><span>Please confirm the root password: ********</span></span></code></pre></div><p>在完成这些后，OrientDB 数据库服务器将成功启动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>INFO OrientDB Server is active v2.2.22 (build fb2b7d321ea8a5a5b18a82237049804aace9e3de). [OServer]</span></span></code></pre></div><p>从现在开始，我们需要用第二个终端来与 OrientDB 服务器进行交互。</p><p>若要强制停止 OrientDB 执行 <code>Ctrl+C</code> 即可。</p><h3 id="配置守护进程" tabindex="-1">配置守护进程 <a class="header-anchor" href="#配置守护进程" aria-label="Permalink to “配置守护进程”">​</a></h3><p>此时，我们可以认为 OrientDB 仅仅是一串 shell 脚本，可以用编辑器打开 <code>/opt/orientdb/bin/orientdb.sh</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /opt/orientdb/bin/orientdb.sh</span></span></code></pre></div><p>在它的首段，我们可以看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span># OrientDB service script</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Copyright (c) OrientDB LTD (http://orientdb.com/)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># chkconfig: 2345 20 80</span></span>
<span class="line"><span># description: OrientDb init script</span></span>
<span class="line"><span># processname: orientdb.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span># You have to SET the OrientDB installation directory here</span></span>
<span class="line"><span>ORIENTDB_DIR=&quot;YOUR_ORIENTDB_INSTALLATION_PATH&quot;</span></span>
<span class="line"><span>ORIENTDB_USER=&quot;USER_YOU_WANT_ORIENTDB_RUN_WITH&quot;</span></span></code></pre></div><p>我们需要配置<code>ORIENTDB_DIR</code> 以及 <code>ORIENTDB_USER</code>.</p><p>然后创建一个用户，例如我们创建一个名为 <code>orientdb</code> 的用户，我们需要输入下面的指令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># useradd -r orientdb -s /sbin/nologin</span></span></code></pre></div><p><code>orientdb</code> 就是我们在 <code>ORIENTDB_USER</code> 处输入的用户。</p><p>再更改 <code>/opt/orientdb</code> 目录的所有权：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chown -R orientdb:orientdb /opt/orientdb</span></span></code></pre></div><p>改变服务器配置文件的权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chmod 640 /opt/orientdb/config/orientdb-server-config.xml</span></span></code></pre></div><h4 id="下载系统守护进程服务" tabindex="-1">下载系统守护进程服务 <a class="header-anchor" href="#下载系统守护进程服务" aria-label="Permalink to “下载系统守护进程服务”">​</a></h4><p>OrientDB 的压缩包包含一个服务文件 <code>/opt/orientdb/bin/orientdb.service</code>。我们将其复制到 <code>/etc/systemd/system</code> 文件夹下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cp /opt/orientdb/bin/orientdb.service /etc/systemd/system</span></span></code></pre></div><p>编辑该服务文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /etc/systemd/system/orientdb.service</span></span></code></pre></div><p>其中 <code>[service]</code> 内容块看起来应该是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Service]</span></span>
<span class="line"><span>User=ORIENTDB_USER</span></span>
<span class="line"><span>Group=ORIENTDB_GROUP</span></span>
<span class="line"><span>ExecStart=$ORIENTDB_HOME/bin/server.sh</span></span></code></pre></div><p>将其改成如下样式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Service]</span></span>
<span class="line"><span>User=orientdb </span></span>
<span class="line"><span>Group=orientdb </span></span>
<span class="line"><span>ExecStart=/opt/orientdb/bin/server.sh</span></span></code></pre></div><p>保存并退出。</p><p>重新加载系统守护进程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl daemon-reload</span></span></code></pre></div><p>启动 OrientDB 并使其开机自启动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl start orientdb</span></span>
<span class="line"><span># systemctl enable orientdb</span></span></code></pre></div><p>确认 OrientDB 的状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl status orientdb</span></span></code></pre></div><p>上述指令应该会输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>● orientdb.service - OrientDB Server</span></span>
<span class="line"><span> Loaded: loaded (/etc/systemd/system/orientdb.service; disabled; vendor preset: enabled)</span></span>
<span class="line"><span> Active: active (running) ...</span></span></code></pre></div><p>流程就是这样了！OrientDB 社区版成功安装并且正确运行在我们的服务器上了。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在这个指导中，我们看到了一些关系型数据库管理系统（RDBMS）以及非关系型数据库管理系统（NoSQL DBMS）的简单对照。我们也安装 OrientDB 社区版的服务器端并完成了其基础的配置。</p><p>这是我们部署完全的 OrientDB 基础设施的第一步，也是我们用于管理大型系统数据的起步。</p><hr>`,55)),t("p",null,[s[5]||(s[5]=e("via: ",-1)),i(a,{href:"https://www.unixmen.com/nosql-install-orientdb-ubuntu-16-04/"},{default:n(()=>[...s[4]||(s[4]=[e("https://www.unixmen.com/nosql-install-orientdb-ubuntu-16-04/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),i(a,{href:"https://www.unixmen.com/author/tutan/"},{default:n(()=>[...s[6]||(s[6]=[e("Giuseppe Molica",-1)])]),_:1}),s[10]||(s[10]=e(" 译者：",-1)),i(a,{href:"https://github.com/a972667237"},{default:n(()=>[...s[7]||(s[7]=[e("a92667237",-1)])]),_:1}),s[11]||(s[11]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[14]||(s[14]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[12]||(s[12]=[e("LCTT",-1)])]),_:1}),s[15]||(s[15]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...s[13]||(s[13]=[e("Linux中国",-1)])]),_:1}),s[16]||(s[16]=e(" 荣誉推出",-1))])])}const v=p(h,[["render",b]]);export{D as __pageData,v as default};
